/*
 * pixman-config.h — OpenWindows freestanding pixman build configuration.
 *
 * Generated for the genuine pixman-0.46.5 subtree (vendor/pixman) on
 * x86-64 Windows with GCC (w64devkit). SIMD backends (mmx/sse2/ssse3/vmx/
 * power8/9/arm/mips/rvv) are all disabled, matching the OpenWindows target.
 * Thread-local-storage is disabled via -DPIXMAN_NO_TLS at build time.
 */
#ifndef PIXMAN_CONFIG_H
#define PIXMAN_CONFIG_H

#define PACKAGE "pixman"
#define VERSION "0.46.5"
#define SIZEOF_LONG 8
#define HAVE_BUILTIN_CLZ 1
#define HAVE_GCC_VECTOR_EXTENSIONS 1

#endif /* PIXMAN_CONFIG_H */
